const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state=0,busy=false,world=null;
const steps=[['01 / MAKE A WISH','Close your eyes.<br>Make a little wish.','Then blow out the candles. Your moment starts here.','Blow out the candles ✧'],['02 / A SLICE OF HAPPINESS','A sweet start<br>to a beautiful year.','Your wish is on its way. Time for a birthday slice!','Cut the cake ♡'],['03 / JUST FOR YOU','You deserve<br>all the little joys.','There is one more little surprise waiting for you.','Open your birthday wish ✦']];
function sync(){const s=steps[state];$('#step').textContent=s[0];$('#prompt').innerHTML=s[1];$('#hint').textContent=s[2];$('#action').textContent=s[3];document.querySelectorAll('.steps span').forEach((e,i)=>e.classList.toggle('active',i<=state));}
async function action(){if(busy)return {stage:state,busy:true};busy=true;$('#action').disabled=true;try{if(state===0){world?.blow();await new Promise(r=>setTimeout(r,reduced?100:900));state=1;sync();}else if(state===1){world?.cut();burst();await new Promise(r=>setTimeout(r,reduced?100:1300));state=2;sync();}else{if(!$('#wish').open)$('#wish').showModal();burst();}}finally{busy=false;$('#action').disabled=false;}return {stage:state,wishOpen:$('#wish').open};}
$('#action').addEventListener('click',action);$('#close').onclick=()=>$('#wish').close();$('#again').onclick=()=>{$('#wish').close();state=0;world?.reset();sync();$('#action').focus();};
const fx=$('#confetti'),ctx=fx.getContext('2d');let confetti=[];function sizeFX(){fx.width=innerWidth;fx.height=innerHeight;}addEventListener('resize',sizeFX);sizeFX();
function burst(){if(reduced)return;confetti=Array.from({length:130},()=>({x:innerWidth/2,y:innerHeight*.5,vx:(Math.random()-.5)*16,vy:-Math.random()*15-3,r:Math.random()*6+3,a:Math.random()*6,spin:(Math.random()-.5)*.2,c:['#f9b8d2','#f4c775','#b9a1ff','#fff0f5'][Math.floor(Math.random()*4)],life:190}));requestAnimationFrame(paintFX);}
function paintFX(){ctx.clearRect(0,0,fx.width,fx.height);confetti.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.14;p.a+=p.spin;p.life--;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.fillStyle=p.c;ctx.globalAlpha=Math.min(1,p.life/30);ctx.fillRect(-p.r/2,-p.r/2,p.r,p.r*.55);ctx.restore();});confetti=confetti.filter(p=>p.life>0);if(confetti.length)requestAnimationFrame(paintFX);}
let ac=null,music=false,timer=null,nextTime=0,noteIndex=0;const tune=[[67,.35],[67,.15],[69,.5],[67,.5],[72,.5],[71,1],[67,.35],[67,.15],[69,.5],[67,.5],[74,.5],[72,1],[67,.35],[67,.15],[79,.5],[76,.5],[72,.5],[71,.5],[69,1],[77,.35],[77,.15],[76,.5],[72,.5],[74,.5],[72,1.5]];
function scheduleMusic(){if(!music)return;while(nextTime<ac.currentTime+.3){const [m,d]=tune[noteIndex];const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=440*2**((m-69)/12);g.gain.setValueAtTime(0,nextTime);g.gain.linearRampToValueAtTime(.07,nextTime+.015);g.gain.exponentialRampToValueAtTime(.001,nextTime+d*.9);o.connect(g);g.connect(ac.destination);o.start(nextTime);o.stop(nextTime+d);nextTime+=d;noteIndex=(noteIndex+1)%tune.length;}timer=setTimeout(scheduleMusic,100);}
$('#sound').onclick=async()=>{try{ac??=new (window.AudioContext||window.webkitAudioContext)();if(music){music=false;clearTimeout(timer);await ac.suspend();}else{await ac.resume();music=true;nextTime=ac.currentTime+.05;noteIndex=0;scheduleMusic();}$('#sound').setAttribute('aria-pressed',String(music));$('#sound span').textContent=music?'Music on':'Music off';$('#sound').setAttribute('aria-label',music?'Turn birthday music off':'Turn birthday music on');}catch{$('#sound span').textContent='Music unavailable';}};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'advance_birthday_celebration',title:'Continue birthday celebration',description:'Blow out candles, cut the cake, or open the birthday wish, using the next visible action.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return action();}})).catch(()=>{});}catch{}}
async function init(){const T=await import('./three.module.js');const canvas=$('#scene');const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setClearColor(0,0);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;
const scene=new T.Scene(),camera=new T.PerspectiveCamera(38,1,.1,60);camera.position.set(4.5,3.6,6.4);camera.lookAt(0,1.05,0);scene.add(new T.HemisphereLight(0xffe3f2,0x352040,2.4));const light=new T.DirectionalLight(0xffe6d3,4);light.position.set(3,6,4);light.castShadow=true;light.shadow.mapSize.set(1024,1024);light.shadow.camera.left=-4;light.shadow.camera.right=4;light.shadow.camera.top=4;light.shadow.camera.bottom=-4;scene.add(light);const rim=new T.PointLight(0xec97ff,12,10);rim.position.set(-3,3,-2);scene.add(rim);
const cake=new T.Group();scene.add(cake);const mat=(c,roughness=.55)=>new T.MeshStandardMaterial({color:c,roughness});const pink=mat(0xed88b1),cream=mat(0xffeadd),sponge=mat(0xe6b487),gold=new T.MeshStandardMaterial({color:0xeac184,metalness:.55,roughness:.28});
function mesh(geo,material,parent,pos){const m=new T.Mesh(geo,material);if(pos)m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
mesh(new T.CylinderGeometry(1.73,1.73,.09,96),gold,cake,[0,.04,0]);mesh(new T.CylinderGeometry(1.62,1.65,.07,96),cream,cake,[0,.12,0]);
const rest=new T.Group(),slice=new T.Group();cake.add(rest,slice);
function sector(radius,height,y,start,end,material,parent){const shape=new T.Shape();shape.moveTo(0,0);shape.lineTo(radius*Math.cos(start),radius*Math.sin(start));shape.absarc(0,0,radius,start,end,false);shape.lineTo(0,0);const geo=new T.ExtrudeGeometry(shape,{depth:height,bevelEnabled:true,bevelThickness:.015,bevelSize:.014,bevelSegments:2,curveSegments:64,steps:1});geo.rotateX(-Math.PI/2);mesh(geo,material,parent,[0,y,0]);}
const layers=[[1.34,.14,.17,cream],[1.32,.26,.31,sponge],[1.33,.07,.57,pink],[1.32,.26,.64,sponge],[1.34,.1,.9,cream],[1.36,.17,1,pink]];
for(const [r,h,y,m]of layers){sector(r,h,y,0,Math.PI/2,m,slice);sector(r,h,y,Math.PI/2,Math.PI*2,m,rest);}
// Frosting pearls follow their cake section when a slice is cut.
for(let i=0;i<44;i++){const a=i/44*Math.PI*2;const p=a<=Math.PI/2?slice:rest;mesh(new T.SphereGeometry(.078,12,10),cream,p,[1.30*Math.cos(a),1.19,-1.30*Math.sin(a)]);}
for(let i=0;i<25;i++){const a=i/25*Math.PI*2;const p=a<=Math.PI/2?slice:rest;const drop=mesh(new T.SphereGeometry(.085,12,10),pink,p,[1.31*Math.cos(a),1.0-Math.sin(i*2)**2*.08,-1.31*Math.sin(a)]);drop.scale.y=1.9;}
for(let i=0;i<65;i++){const a=i*2.4,r=.36+Math.sqrt((i+.5)/65)*.76;const p=(a%(Math.PI*2))<=Math.PI/2?slice:rest;const spr=mesh(new T.BoxGeometry(.065,.025,.025),i%3===0?gold:cream,p,[r*Math.cos(a),1.19,-r*Math.sin(a)]);spr.rotation.y=a;}
const flames=[],glows=[];for(let i=0;i<5;i++){const a=i/5*Math.PI*2,x=Math.cos(a)*.58,z=Math.sin(a)*.58;mesh(new T.CylinderGeometry(.04,.04,.46,12),i%2?cream:mat(0xbe91ca),rest,[x,1.42,z]);for(let j=0;j<5;j++){const band=mesh(new T.TorusGeometry(.041,.007,5,12),gold,rest,[x,1.24+j*.075,z]);band.rotation.x=Math.PI/2;}mesh(new T.CylinderGeometry(.009,.009,.065,8),mat(0x453040),rest,[x,1.67,z]);const flame=mesh(new T.SphereGeometry(.06,16,12),new T.MeshBasicMaterial({color:0xffd26a}),rest,[x,1.76,z]);flame.scale.set(.7,1.8,.7);flames.push(flame);const glow=new T.PointLight(0xffae58,.55,1.7);glow.position.set(x,1.75,z);rest.add(glow);glows.push(glow);}
const ground=mesh(new T.CircleGeometry(3.5,64),new T.ShadowMaterial({opacity:.2}),scene,[0,-.02,0]);ground.rotation.x=-Math.PI/2;ground.castShadow=false;
const stars=new T.BufferGeometry();const points=[];for(let i=0;i<70;i++)points.push((Math.random()-.5)*7,Math.random()*4-.1,(Math.random()-.5)*6);stars.setAttribute('position',new T.Float32BufferAttribute(points,3));const dust=new T.Points(stars,new T.PointsMaterial({color:0xf4c775,size:.025,transparent:true,opacity:.6}));scene.add(dust);
let blown=false,cut=false,start=0,rot=0,dragging=false,lastX=0;
world={blow(){blown=true;flames.forEach(f=>f.visible=false);glows.forEach(g=>g.visible=false);},cut(){cut=true;start=performance.now();},reset(){blown=false;cut=false;slice.position.set(0,0,0);slice.rotation.set(0,0,0);flames.forEach(f=>f.visible=true);glows.forEach(g=>g.visible=true);}};
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(dragging){rot+=(e.clientX-lastX)*.009;lastX=e.clientX;}});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();rot+=e.key==='ArrowLeft'?-.2:.2;}});
function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas);resize();$('#load').hidden=true;
function frame(time){requestAnimationFrame(frame);if(document.hidden)return;const t=time*.001;cake.rotation.y=rot+(reduced?0:Math.sin(t*.23)*.13);if(!blown)flames.forEach((f,i)=>{f.scale.y=1.8+(reduced?0:Math.sin(t*8+i)*.22);});if(cut){const p=reduced?1:Math.min((time-start)/1200,1),ease=1-(1-p)**3;slice.position.set(.58*ease,.08*Math.sin(p*Math.PI),-.58*ease);}if(!reduced)dust.rotation.y=t*.025;renderer.render(scene,camera);}requestAnimationFrame(frame);
}
init().catch(e=>{$('#load').textContent='3D cake could not load on this browser. You can still make your wish below.';$('#load').style.padding='0 40px';$('.drag').hidden=true;console.error('3D birthday scene unavailable',e);});
